{"files":{"engine.py":"import sys
import time

INF = 100000000
MATE = 100000
VAL = {"p": 100, "n": 320, "b": 330, "r": 500, "q": 900, "k": 20000}
PROM = {1: "n", 2: "b", 3: "r", 4: "q"}

CASTLE = 1
EP_CAPTURE = 2
DOUBLE_PUSH = 4


def attacked(p, sq, by):
    if sq < 0 or sq >= 64:
        return False
    b = p.b
    r, f = divmod(sq, 8)
    rr = r - 1 if by == 0 else r + 1
    pawn = "P" if by == 0 else "p"
    if 0 <= rr < 8:
        for ff in (f - 1, f + 1):
            if 0 <= ff < 8 and b[rr * 8 + ff] == pawn:
                return True
    knight = "N" if by == 0 else "n"
    for dr, df in ((2, 1), (2, -1), (-2, 1), (-2, -1), (1, 2), (1, -2), (-1, 2), (-1, -2)):
        x, y = r + dr, f + df
        if 0 <= x < 8 and 0 <= y < 8 and b[x * 8 + y] == knight:
            return True
    king_piece = "K" if by == 0 else "k"
    for dr in (-1, 0, 1):
        for df in (-1, 0, 1):
            if dr or df:
                x, y = r + dr, f + df
                if 0 <= x < 8 and 0 <= y < 8 and b[x * 8 + y] == king_piece:
                    return True
    for dr, df, chars in ((1, 0, "rq"), (-1, 0, "rq"), (0, 1, "rq"), (0, -1, "rq"), (1, 1, "bq"), (1, -1, "bq"), (-1, 1, "bq"), (-1, -1, "bq")):
        x, y = r + dr, f + df
        while 0 <= x < 8 and 0 <= y < 8:
            piece = b[x * 8 + y]
            if piece != ".":
                if piece.isupper() == (by == 0) and piece.lower() in chars:
                    return True
                break
            x += dr
            y += df
    return False


def king(p, side):
    wanted = "K" if side == 0 else "k"
    found = -1
    for sq, piece in enumerate(p.b):
        if piece == wanted:
            if found != -1:
                return -1
            found = sq
    return found


def square(text):
    if len(text) != 2 or text[0] not in "abcdefgh" or text[1] not in "12345678":
        raise ValueError("bad square")
    return ord(text[0]) - 97 + 8 * (ord(text[1]) - 49)


def encode(a, z, promotion=0, flags=0):
    return a | (z << 6) | (promotion << 12) | (flags << 16)


def effective_ep(p):
    ep = p.ep
    if ep < 0 or ep >= 64 or p.b[ep] != ".":
        return -1
    r, f = divmod(ep, 8)
    if p.side == 0:
        if r != 5 or p.b[ep - 8] != "p":
            return -1
        pawn = "P"
    else:
        if r != 2 or p.b[ep + 8] != "P":
            return -1
        pawn = "p"
    for ff in (f - 1, f + 1):
        if 0 <= ff < 8 and p.b[r * 8 + ff] == pawn:
            return ep
    return -1


def position_key(p):
    return (tuple(p.b), p.side, p.cast, effective_ep(p))


class Position:
    def __init__(self, board, side, cast, ep, half, full):
        if len(board) != 64 or side not in (0, 1) or cast < 0 or ep < -1 or ep >= 64:
            raise ValueError("bad position")
        if any(x not in ".PNBRQKpnbrqk" for x in board):
            raise ValueError("bad piece")
        if sum(x == "K" for x in board) != 1 or sum(x == "k" for x in board) != 1:
            raise ValueError("bad kings")
        if half < 0 or full < 1:
            raise ValueError("bad clocks")
        self.b = list(board)
        self.side = side
        self.cast = cast
        self.ep = ep
        self.half = half
        self.full = full
        self.rep_history = []
        self.rep_counts = {}
        key = position_key(self)
        self.rep_history.append(key)
        self.rep_counts[key] = 1

    @classmethod
    def fen(cls, text):
        fields = text.split()
        if len(fields) != 6:
            raise ValueError("fen")
        rows = fields[0].split("/")
        if len(rows) != 8:
            raise ValueError("ranks")
        board = []
        for row in rows:
            expanded = []
            for ch in row:
                if ch.isdigit():
                    n = ord(ch) - 48
                    if not 1 <= n <= 8:
                        raise ValueError("empty")
                    expanded.extend(["."] * n)
                elif ch in "PNBRQKpnbrqk":
                    expanded.append(ch)
                else:
                    raise ValueError("piece")
            if len(expanded) != 8:
                raise ValueError("width")
            board[0:0] = expanded
        if fields[1] not in ("w", "b"):
            raise ValueError("side")
        rights = fields[2]
        if rights == "-":
            cast = 0
        else:
            if not rights or any(ch not in "KQkq" for ch in rights) or len(set(rights)) != len(rights):
                raise ValueError("rights")
            cast = sum(1 << i for i, ch in enumerate("KQkq") if ch in rights)
        ep = -1 if fields[3] == "-" else square(fields[3])
        if ep != -1 and ep // 8 not in (2, 5):
            raise ValueError("ep")
        try:
            half, full = int(fields[4]), int(fields[5])
        except ValueError as exc:
            raise ValueError("clocks") from exc
        return cls(board, 0 if fields[1] == "w" else 1, cast, ep, half, full)

    @classmethod
    def start(cls):
        return cls.fen("rnbqkbnr/pppppppp/8/8/8/8/PPPPPPPP/RNBQKBNR w KQkq - 0 1")


class Delta:
    __slots__ = ("squares", "side", "cast", "ep", "half", "full", "new_key")

    def __init__(self, p):
        self.squares = []
        self.side = p.side
        self.cast = p.cast
        self.ep = p.ep
        self.half = p.half
        self.full = p.full
        self.new_key = None


def pseudo(p, captures=False):
    b, side, white = p.b, p.side, p.side == 0
    moves = []

    def add(a, z, promotion=0, flags=0, capture=False):
        if not captures or capture or promotion:
            moves.append(encode(a, z, promotion, flags))

    for a, piece in enumerate(b):
        if piece == "." or piece.isupper() != white:
            continue
        r, f = divmod(a, 8)
        typ = piece.lower()
        if typ == "p":
            direction = 8 if white else -8
            z = a + direction
            final = 7 if white else 0
            if 0 <= z < 64 and b[z] == ".":
                if z // 8 == final:
                    for promotion in (4, 3, 2, 1):
                        add(a, z, promotion)
                else:
                    add(a, z)
                    if not captures and r == (1 if white else 6) and b[a + 2 * direction] == ".":
                        add(a, a + 2 * direction, 0, DOUBLE_PUSH)
            for df in (-1, 1):
                ff = f + df
                if not 0 <= ff < 8:
                    continue
                z = a + direction + df
                if not 0 <= z < 64:
                    continue
                target = b[z]
                if target != "." and target.isupper() != white:
                    if target.lower() == "k":
                        continue
                    if z // 8 == final:
                        for promotion in (4, 3, 2, 1):
                            add(a, z, promotion, 0, True)
                    else:
                        add(a, z, 0, 0, True)
                elif z == p.ep:
                    cap = z - 8 if white else z + 8
                    if 0 <= cap < 64 and b[cap] == ("p" if white else "P"):
                        add(a, z, 0, EP_CAPTURE, True)
        elif typ == "n":
            for dr, df in ((2, 1), (2, -1), (-2, 1), (-2, -1), (1, 2), (1, -2), (-1, 2), (-1, -2)):
                x, y = r + dr, f + df
                if 0 <= x < 8 and 0 <= y < 8:
                    z = x * 8 + y
                    if (b[z] == "." or b[z].isupper() != white) and (b[z] == "." or b[z].lower() != "k"):
                        add(a, z, 0, 0, b[z] != ".")
        elif typ in "brq":
            directions = []
            if typ in "bq":
                directions += ((1, 1), (1, -1), (-1, 1), (-1, -1))
            if typ in "rq":
                directions += ((1, 0), (-1, 0), (0, 1), (0, -1))
            for dr, df in directions:
                x, y = r + dr, f + df
                while 0 <= x < 8 and 0 <= y < 8:
                    z = x * 8 + y
                    if b[z] == ".":
                        add(a, z)
                    else:
                        if b[z].isupper() != white and b[z].lower() != "k":
                            add(a, z, 0, 0, True)
                        break
                    x += dr
                    y += df
        else:
            for dr in (-1, 0, 1):
                for df in (-1, 0, 1):
                    if dr or df:
                        x, y = r + dr, f + df
                        if 0 <= x < 8 and 0 <= y < 8:
                            z = x * 8 + y
                            if (b[z] == "." or b[z].isupper() != white) and (b[z] == "." or b[z].lower() != "k"):
                                add(a, z, 0, 0, b[z] != ".")
            if not captures and a == (4 if white else 60) and not attacked(p, a, side ^ 1):
                castles = ((1, 6, (5, 6), 1, 7), (2, 2, (1, 2, 3), 1, 0)) if white else ((4, 62, (61, 62), 1, 63), (8, 58, (57, 58, 59), 1, 56))
                for bit, dest, empty, _, rook in castles:
                    if p.cast & bit and all(b[s] == "." for s in empty) and b[rook] == ("R" if white else "r"):
                        transit = empty[-2] if dest in (6, 62) else empty[-2]
                        if not attacked(p, transit, side ^ 1) and not attacked(p, dest, side ^ 1):
                            add(a, dest, 0, CASTLE)
    return moves


def make_move(p, move):
    a, z = move & 63, (move >> 6) & 63
    promotion, flags = (move >> 12) & 15, move >> 16
    if a == z or not 0 <= a < 64 or not 0 <= z < 64 or flags & ~7:
        raise ValueError("move")
    piece, target, white = p.b[a], p.b[z], p.side == 0
    if piece == "." or piece.isupper() != white or (target != "." and target.isupper() == white) or target.lower() == "k":
        raise ValueError("occupancy")
    is_castle, is_ep, is_double = bool(flags & CASTLE), bool(flags & EP_CAPTURE), bool(flags & DOUBLE_PUSH)
    if sum((is_castle, is_ep, is_double)) > 1:
        raise ValueError("flags")
    capture_sq = z if target != "." else -1
    captured = target
    rook_from = rook_to = -1
    if is_ep:
        if piece.lower() != "p" or z != p.ep or target != ".":
            raise ValueError("ep")
        capture_sq = z - 8 if white else z + 8
        captured = p.b[capture_sq]
        if captured != ("p" if white else "P"):
            raise ValueError("ep pawn")
    if is_double:
        if piece.lower() != "p" or abs(z - a) != 16 or a % 8 != z % 8 or p.b[(a + z) // 2] != "." or target != ".":
            raise ValueError("double")
        if (a // 8, z // 8) != ((1, 3) if white else (6, 4)):
            raise ValueError("rank")
    if is_castle:
        mapping = {(4, 6): (7, 5, 1), (4, 2): (0, 3, 2), (60, 62): (63, 61, 4), (60, 58): (56, 59, 8)}
        if piece.lower() != "k" or promotion or target != "." or (a, z) not in mapping:
            raise ValueError("castle")
        rook_from, rook_to, bit = mapping[(a, z)]
        if not (p.cast & bit) or p.b[rook_from] != ("R" if white else "r"):
            raise ValueError("castle right")
    final = 7 if white else 0
    if promotion:
        if promotion not in (1, 2, 3, 4) or piece.lower() != "p" or z // 8 != final:
            raise ValueError("promotion")
    elif piece.lower() == "p" and z // 8 == final:
        raise ValueError("promotion required")

    delta = Delta(p)
    touched = set()

    def set_square(sq, value):
        if p.b[sq] != value:
            if sq not in touched:
                delta.squares.append((sq, p.b[sq]))
                touched.add(sq)
            p.b[sq] = value

    set_square(a, ".")
    if capture_sq >= 0:
        set_square(capture_sq, ".")
    moved = piece
    if promotion:
        moved = ("NBRQ" if white else "nbrq")[promotion - 1]
    set_square(z, moved)
    if is_castle:
        set_square(rook_from, ".")
        set_square(rook_to, "R" if white else "r")

    rights = p.cast
    if piece == "K":
        rights &= 12
    elif piece == "k":
        rights &= 3
    elif piece == "R":
        if a == 0:
            rights &= ~2
        elif a == 7:
            rights &= ~1
    elif piece == "r":
        if a == 56:
            rights &= ~8
        elif a == 63:
            rights &= ~4
    if captured == "R":
        if capture_sq == 0:
            rights &= ~2
        elif capture_sq == 7:
            rights &= ~1
    elif captured == "r":
        if capture_sq == 56:
            rights &= ~8
        elif capture_sq == 63:
            rights &= ~4
    p.cast = rights
    p.ep = (a + z) // 2 if is_double else -1
    p.half = 0 if piece.lower() == "p" or capture_sq >= 0 else p.half + 1
    p.full += 1 if p.side == 1 else 0
    p.side ^= 1
    key = position_key(p)
    p.rep_history.append(key)
    p.rep_counts[key] = p.rep_counts.get(key, 0) + 1
    delta.new_key = key
    return delta


def unmake_move(p, delta):
    if not p.rep_history or p.rep_history[-1] != delta.new_key:
        raise ValueError("unmake")
    p.rep_history.pop()
    count = p.rep_counts.get(delta.new_key, 0)
    if count <= 1:
        p.rep_counts.pop(delta.new_key, None)
    else:
        p.rep_counts[delta.new_key] = count - 1
    for sq, old in reversed(delta.squares):
        p.b[sq] = old
    p.side, p.cast, p.ep, p.half, p.full = delta.side, delta.cast, delta.ep, delta.half, delta.full


def legal(p, captures=False):
    result, side = [], p.side
    for move in pseudo(p, captures):
        delta = make_move(p, move)
        try:
            ksq = king(p, side)
            if ksq >= 0 and not attacked(p, ksq, side ^ 1):
                result.append(move)
        finally:
            unmake_move(p, delta)
    return result


def notation(move):
    a, z, promotion = move & 63, (move >> 6) & 63, (move >> 12) & 15
    return "abcdefgh"[a & 7] + str(a // 8 + 1) + "abcdefgh"[z & 7] + str(z // 8 + 1) + (PROM[promotion] if promotion else "")


class Engine:
    def __init__(self):
        self.pos = Position.start()
        self.tt, self.history, self.killers = {}, {}, {}
        self.nodes = 0
        self.deadline = 0.0

    def evaluate(self, p):
        score = phase = wb = bb = pawns = 0
        wp, bp = [0] * 8, [0] * 8
        for piece in p.b:
            if piece != "." and piece.lower() not in ("p", "k"):
                phase += VAL[piece.lower()]
        for sq, piece in enumerate(p.b):
            if piece == ".":
                continue
            typ, sign = piece.lower(), (1 if piece.isupper() else -1)
            score += sign * VAL[typ]
            r, f = divmod(sq, 8)
            rr = r if sign == 1 else 7 - r
            center = 7 - abs(2 * f - 7) - abs(2 * rr - 7)
            if typ == "p":
                pawns += 1
                (wp if sign == 1 else bp)[f] += 1
                score += sign * (rr * 10 + center * 2)
                ranks = range(r + 1, 8) if sign == 1 else range(r - 1, -1, -1)
                passed = all(not (0 <= f2 < 8 and p.b[r2 * 8 + f2] == ("p" if sign == 1 else "P")) for r2 in ranks for f2 in (f - 1, f, f + 1))
                if passed:
                    score += sign * (18 + rr * 8)
            elif typ == "n":
                score += sign * center * 10
            elif typ == "b":
                score += sign * center * 5
                wb += sign == 1
                bb += sign == -1
            elif typ == "r":
                score += sign * (rr * 3 + (5 if f in (3, 4) else 0))
                if (wp if sign == 1 else bp)[f] == 0:
                    score += sign * 12
            elif typ == "q":
                score += sign * center * 2
            else:
                score += sign * (-center * 3 if phase > 2600 else center * 10)
        if wb >= 2:
            score += 30
        if bb >= 2:
            score -= 30
        for n in wp:
            score -= max(0, n - 1) * 10
        for n in bp:
            score += max(0, n - 1) * 10
        for f, n in enumerate(wp):
            if n and (f == 0 or wp[f - 1] == 0) and (f == 7 or wp[f + 1] == 0):
                score -= 10 * n
        for f, n in enumerate(bp):
            if n and (f == 0 or bp[f - 1] == 0) and (f == 7 or bp[f + 1] == 0):
                score += 10 * n
        if pawns == 0 and (phase == 0 or phase == 320 or (phase == 330 and wb + bb == 1)):
            return 0
        return score if p.side == 0 else -score

    def check_time(self, force=False):
        self.nodes += 1
        if force or (self.nodes & 31) == 0:
            if time.perf_counter() >= self.deadline:
                raise TimeoutError

    def state_key(self, p):
        identity = position_key(p)
        return identity, min(p.half, 100), p.rep_counts.get(identity, 1)

    def move_score(self, p, move, tt_move, ply):
        a, z = move & 63, (move >> 6) & 63
        promotion, flags = (move >> 12) & 15, move >> 16
        score = 10000000 if move == tt_move else 0
        captured = "p" if flags & EP_CAPTURE else p.b[z]
        if captured != ".":
            score += 1000000 + VAL[captured.lower()] * 10 - VAL[p.b[a].lower()]
        if promotion:
            score += 800000 + promotion * 10000
        if self.killers.get(ply) == move:
            score += 500000
        score += self.history.get((p.side, a, z), 0)
        if flags & CASTLE:
            score += 100
        return score

    def qsearch(self, p, alpha, beta, ply):
        self.check_time()
        checked = attacked(p, king(p, p.side), p.side ^ 1)
        if ply >= 12:
            moves = legal(p)
            if not moves:
                return -MATE + ply if checked else 0
            return self.evaluate(p)
        stand = -INF
        if not checked:
            stand = self.evaluate(p)
            if stand >= beta:
                return stand
            alpha = max(alpha, stand)
        moves = legal(p, False if checked else True)
        self.check_time()
        if not moves:
            return -MATE + ply if checked else stand
        moves.sort(key=lambda m: self.move_score(p, m, -1, ply), reverse=True)
        for move in moves:
            self.check_time()
            delta = make_move(p, move)
            try:
                score = -self.qsearch(p, -beta, -alpha, ply + 1)
            finally:
                unmake_move(p, delta)
            if score >= beta:
                return score
            alpha = max(alpha, score)
        return alpha

    def search(self, p, depth, alpha, beta, ply):
        self.check_time()
        if depth <= 0:
            return self.qsearch(p, alpha, beta, ply)
        key = self.state_key(p)
        original_alpha, original_beta = alpha, beta
        entry = self.tt.get(key)
        tt_move = -1
        if entry:
            entry_depth, stored, flag, entry_ply, tt_move = entry
            if entry_depth >= depth:
                score = stored
                if score <= -MATE + 1000:
                    score += ply - entry_ply
                elif score >= MATE - 1000:
                    score -= ply - entry_ply
                if flag == 0:
                    return score
                if flag == 1:
                    alpha = max(alpha, score)
                else:
                    beta = min(beta, score)
                if alpha >= beta:
                    return score
        moves = legal(p)
        self.check_time()
        if not moves:
            return -MATE + ply if attacked(p, king(p, p.side), p.side ^ 1) else 0
        moves.sort(key=lambda m: self.move_score(p, m, tt_move, ply), reverse=True)
        best, best_move = -INF, moves[0]
        for move in moves:
            self.check_time()
            delta = make_move(p, move)
            try:
                next_depth = depth - 1
                if depth <= 2 and attacked(p, king(p, p.side), p.side ^ 1):
                    next_depth += 1
                score = -self.search(p, next_depth, -beta, -alpha, ply + 1)
            finally:
                unmake_move(p, delta)
            if score > best:
                best, best_move = score, move
            alpha = max(alpha, score)
            if alpha >= beta:
                if p.b[move & 63].lower() != "p" and p.b[(move >> 6) & 63] == "." and not ((move >> 12) & 15):
                    self.killers[ply] = move
                    hkey = (p.side, move & 63, (move >> 6) & 63)
                    self.history[hkey] = min(10000, self.history.get(hkey, 0) + depth * depth)
                break
        flag = 2 if best <= original_alpha else 1 if best >= original_beta else 0
        store = best - ply if best <= -MATE + 1000 else best + ply if best >= MATE - 1000 else best
        self.tt[key] = (depth, store, flag, ply, best_move)
        if len(self.tt) > 180000:
            self.tt.clear()
        return best

    def root(self, p, moves, depth):
        ordered = sorted(moves, key=lambda m: self.move_score(p, m, -1, 0), reverse=True)
        alpha, best, best_move = -INF, -INF, ordered[0]
        for move in ordered:
            self.check_time()
            delta = make_move(p, move)
            try:
                score = -self.search(p, depth - 1, -INF, -alpha, 1)
            finally:
                unmake_move(p, delta)
            if score > best:
                best, best_move = score, move
            alpha = max(alpha, score)
        return best, best_move

    def think(self, millis):
        self.nodes = 0
        self.deadline = time.perf_counter() + max(0.0005, millis / 1000.0 * 0.82)
        moves = legal(self.pos)
        if not moves:
            return "0000"
        best = moves[0]
        if millis <= 4:
            return notation(best)
        try:
            self.check_time(True)
        except TimeoutError:
            return notation(best)
        for depth in range(1, 64):
            try:
                score, move = self.root(self.pos, moves, depth)
            except TimeoutError:
                break
            best = move
            if abs(score) > MATE - 1000:
                break
        return notation(best)

    def setpos(self, args):
        try:
            if len(args) >= 2 and args[1] == "startpos":
                candidate, index = Position.start(), 2
            elif len(args) >= 8 and args[1] == "fen":
                candidate, index = Position.fen(" ".join(args[2:8])), 8
            else:
                return False
            if index < len(args):
                if args[index] != "moves":
                    return False
                for token in args[index + 1:]:
                    chosen = next((m for m in legal(candidate) if notation(m) == token), None)
                    if chosen is None:
                        return False
                    make_move(candidate, chosen)
            self.pos = candidate
            return True
        except (ValueError, IndexError):
            return False


def main():
    engine = Engine()
    for line in sys.stdin:
        args = line.strip().split()
        if not args:
            continue
        command = args[0]
        if command == "uci":
            print("id name PythonScratch")
            print("id author Codex")
            print("uciok")
            sys.stdout.flush()
        elif command == "isready":
            print("readyok")
            sys.stdout.flush()
        elif command == "ucinewgame":
            engine.tt.clear()
            engine.history.clear()
            engine.killers.clear()
            engine.pos = Position.start()
        elif command == "position":
            engine.setpos(args)
        elif command == "go":
            millis = 1000
            if "movetime" in args:
                try:
                    millis = max(1, int(args[args.index("movetime") + 1]))
                except (ValueError, IndexError):
                    millis = 1000
            print("bestmove " + engine.think(millis))
            sys.stdout.flush()
        elif command == "quit":
            break


if __name__ == "__main__":
    main()
